"""Embedded Natural Earth 110m coastline data.

Source: naturalearthdata.com/downloads/110m-physical-vectors/110m-coastline/
License: Public Domain / CC0
Coordinates: 1 decimal place (~1.1 km resolution)
Generated by: scripts/build_coastline.py
"""

from __future__ import annotations

import base64
import gzip
import json
from typing import Final

# Compressed (gzip + base64) NE 110m coastline polylines.
# Each inner list is a list of (longitude, latitude) tuples.
_COASTLINE_B64: Final[str] = (
    ""
)

_COASTLINE_CACHE: list[list[list[float]]] | None = None


def load_coastlines() -> list[list[list[float]]]:
    """Decode and cache the embedded coastline polylines.

    Returns a list of polyline segments, where each segment is a list of
    [longitude, latitude] coordinate pairs.
    """
    global _COASTLINE_CACHE  # noqa: PLW0603
    if _COASTLINE_CACHE is None:
        raw = gzip.decompress(base64.b64decode(_COASTLINE_B64))
        _COASTLINE_CACHE = json.loads(raw)
    return _COASTLINE_CACHE
